window.kbPageData["views/entry/k-584226db832d2835"] = {"key":"entry/k-584226db832d2835","state":{"route":"entry/k-584226db832d2835"},"node":{"id":"k-584226db832d2835","mode":"k","title":"物质与意识","type":"原理与机制","domain":"哲学","reading":"","intro":"","priority":100,"aliases":["唯物论 · 物质和意识的辩证关系和方法论要求"],"qs":["政治理论必刷100题#4","政治理论必刷100题#8","国考 2025 副省级 申论#5","江苏 2024 A类 行测#9"],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"repeatPositions":0,"reviewSet":"多题条目","independentCount":4,"reviewDoubt":"《物质与意识》江苏 2024 A类 行测 · 第 9 题（江苏 2024 A类 行测#9）仍需核查官方答案说明是否将D项的“观察动物活动所获得的信息”理解为自然现象所呈现的信息，还是人们经归纳形成的预报经验。检索未找到该题的官方答案说明，教材的分类口径无法确认命题方排除D项的具体依据。","tags":{"主类":["原理与机制"],"出处性质":["专项题解析","理论手册"],"学科":["哲学"],"来源主题":["马克思主义哲学"],"资料类别":["政治理论专项","非时政"]},"directorySummary":"在辩证唯物主义中，物质决定意识，意识是对客观存在的能动反映。意识能够指导实践，并通过实践反作用于客观世界。","review":{"title":"物质与意识","type":"原理与机制","definition":"在辩证唯物主义中，物质决定意识，意识是对客观存在的能动反映。意识能够指导实践，并通过实践反作用于客观世界。","explanation":"物质决定意识要求人们从客观实际出发。意识的能动性体现在认识事物及其联系、指导实践两个方面。符合客观实际和规律的认识能够指导实践、促进事物发展，错误的认识若用于指导实践，则可能阻碍事物发展。","basis":"据关联原题及所列出处编释。","references":[{"source":"web-e9aa10bde33630a1","location":"第1章“信息管理理论综述”，“按信息产生领域划分”","quote":"按信息产生领域可将信息划分为自然信息与社会信息。"}],"examFocus":{"政治理论必刷100题#4":"结合宏观调控的事例，区分意识对物质的反作用与这种作用在一定条件下产生的具体效果。","政治理论必刷100题#8":"结合典故中的心理活动和实际结果，辨别意识对人的作用与意识、物质之间的决定关系。","江苏 2024 A类 行测#9":"区分蜻蜓低飞这一观察现象、由观察形成的经验和经验所反映的哲学原理。","国考 2025 副省级 申论#5":"结合旧粮仓改造等材料，论证原有条件、人的行动和转化结果之间的关系。"}},"aspects":[{"title":"意识反作用的性质与条件","uses":[{"unit":"Q1","role":"直接考查","use":"本题为选非题，答案为B。我国发展中的不平衡、不协调、不可持续问题是制定宏观调控政策的客观依据。科学的调控政策付诸实施可以推动问题解决，B项把特定条件下的促进作用概括为意识的一般作用，因而错误。","evidence":"意识对物质具有促进作用，科学的宏观调控政策可以促进问题的解决和经济社会发展","qids":["政治理论必刷100题#4"]},{"unit":"Q2","role":"直接考查","use":"本题要求选出对应错误的一项，答案为C。“画饼充饥”“望梅止渴”涉及想象或心理暗示，C项将这类影响说成意识对物质的决定作用，颠倒了二者的决定关系。","evidence":"画饼充饥，望梅止渴——意识对物质具有决定作用","qids":["政治理论必刷100题#8"]}]},{"title":"意识对客观联系的认识","uses":[{"unit":"Q4","role":"直接考查","use":"本题所给答案为C。题干问预报经验体现的哲理，C项对应人们从蜻蜓低飞与天气变化的观察中归纳联系的认识活动。D项讨论的是观察所得信息的类别。按信息产生领域划分，蜻蜓低飞所呈现的现象可视为自然信息，人们据此形成的预报经验则是对现象联系的归纳。把观察所得一概归为社会信息的说法缺乏依据，命题采用的分类口径仍待核实。[清华大学出版社《信息管理理论综述》](https://www.tup.tsinghua.edu.cn/upload/books/yz/034039-01.pdf)","evidence":"人类通过意识活动把握客观事物运动变化的规律","qids":["江苏 2024 A类 行测#9"]}]},{"title":"发挥主观能动性的客观条件","uses":[{"unit":"Q3","role":"解题依据","use":"本题要求结合材料和实际，论述人在特定条件下如何促成劣势向优势转化。今州粮仓改造以保存完好的旧仓及粮食文化为基础，通过修缮和引入展演等活动，让失去原有储粮功能的空间获得新的公共文化用途。","evidence":"事物的劣势在特定条件下可以转化为优势，这种转化往往有赖于人的主观能动性","qids":["国考 2025 副省级 申论#5"]}]}],"sources":[{"id":"8c16fff9f9ff2785","label":"唯物论 · 物质和意识的辩证关系和方法论要求","topic":"马克思主义哲学","category":"非时政","text":"三、物质和意识的辩证关系和方法论要求\n辩证关系：物质决定意识；意识对物质具有反作用。\n方法论：一切从实际出发；在尊重客观规律的基础上，充分发挥人的主观能动性。","source":{"doc":"3ccc56f4000d1642c2d1","first":2,"last":2,"page":2,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"questions":{"政治理论必刷100题#4":{"paper":"政治理论必刷100题","n":4,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",1],"asrc":["国省考政治理论必刷100题.pdf",33],"card":"24c96fea0aaf576371de8170","links":[{"id":"k-584226db832d2835","role":"直接考查","why":"意识的能动作用具有双重性，正确的意识促进事物发展，错误的意识会阻碍事物发展。"}]},"政治理论必刷100题#8":{"paper":"政治理论必刷100题","n":8,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",2],"asrc":["国省考政治理论必刷100题.pdf",35],"card":"f53a602bfaff93b42ee1fbe7","links":[{"id":"k-584226db832d2835","role":"直接考查","why":"典故中的心理暗示体现意识的反作用，物质决定意识。"}]},"国考 2025 副省级 申论#5":{"paper":"国考 2025 副省级 申论","n":5,"mod":"申论","src":["7543a550935cd0cc16be.pdf",4],"asrc":["3f81b5d39fbc5b1d205d.pdf",3],"card":"20bebea5131176e9c1fce49d","links":[{"id":"k-584226db832d2835","role":"直接考查","why":"题目要求阐明人如何立足客观条件，通过主动实践促成转化。"}]},"江苏 2024 A类 行测#9":{"paper":"江苏 2024 A类 行测","n":9,"mod":"常识判断","src":["f8fec75f67d6d1ba5759.pdf",2],"asrc":["0126a1c8aceee632ea2b.pdf",3],"card":"eb776cae7db026319d933503","links":[{"id":"k-584226db832d2835","role":"直接考查","why":"从反复观察到的现象中概括客观联系，体现了意识能动地认识客观世界。"}]}},"terms":{},"references":{"web-e9aa10bde33630a1":{"name":"清华大学出版社教材试读《信息管理理论综述》","url":"https://www.tup.tsinghua.edu.cn/upload/books/yz/034039-01.pdf"}},"topics":[],"units":{"k-584226db832d2835":[["政治理论必刷100题#4"],["政治理论必刷100题#8"],["国考 2025 副省级 申论#5"],["江苏 2024 A类 行测#9"]]}};
